import React, { useState, useEffect } from 'react';
import { useDispatch } from 'react-redux';
import { toast } from 'react-toastify';
import { createEmployee, updateEmployee } from '../../store/employeeSlice';

const inputStyle = {
  width: '100%', boxSizing: 'border-box',
  border: '1.5px solid #e5e7eb', borderRadius: 10,
  padding: '10px 14px', fontSize: 14, outline: 'none',
  fontFamily: 'inherit', color: '#111827', background: '#fff',
  transition: 'border-color 0.15s',
};

const EmployeeForm = ({ employee, onSubmit, onCancel }) => {
  const dispatch = useDispatch();
  const [loading, setLoading] = useState(false);
  const [form, setForm] = useState({
    full_name: '', position: '', department: '', phone: '', email: '',
    role: 'employee', username: '', password: '',
  });

  useEffect(() => {
    if (employee) {
      setForm({
        full_name: employee.full_name || '',
        position: employee.position || '',
        department: employee.department || '',
        phone: employee.phone || '',
        email: employee.email || '',
        role: employee.role || 'employee',
        username: '',
        password: '',
      });
    } else {
      // Сброс формы при создании нового
      setForm({
        full_name: '', position: '', department: '', phone: '', email: '',
        role: 'employee', username: '', password: '',
      });
    }
  }, [employee]);

  const handleChange = (e) => setForm({ ...form, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    
    // Валидация
    if (!form.full_name || !form.position) {
      toast.error('Заполните обязательные поля (ФИО, должность)');
      return;
    }
    
    if (!employee && (!form.username || !form.password)) {
      toast.error('Для нового сотрудника укажите логин и пароль');
      return;
    }
    
    setLoading(true);
    try {
      if (employee) {
        // При редактировании НЕ отправляем username и password
        const { username, password, ...updateData } = form;
        await dispatch(updateEmployee({ id: employee.id, ...updateData })).unwrap();
        toast.success('Данные сотрудника обновлены');
      } else {
        await dispatch(createEmployee(form)).unwrap();
        toast.success('Сотрудник успешно добавлен');
      }
      onSubmit();
    } catch (err) {
      // Показываем конкретную ошибку от сервера если есть
      const errorMessage = err?.response?.data?.detail || 
                          err?.response?.data?.error ||
                          err?.detail || 
                          err?.message || 
                          'Ошибка сохранения';
      toast.error(errorMessage);
    } finally {
      setLoading(false);
    }
  };

  // Фокус на первом поле при открытии
  useEffect(() => {
    const firstInput = document.querySelector('[name="full_name"]');
    if (firstInput) firstInput.focus();
  }, [employee]);

  return (
    <div style={{ 
      background: '#fff', 
      borderRadius: 16, 
      padding: 24, 
      border: '1px solid #e5e7eb', 
      boxShadow: '0 4px 16px rgba(0,0,0,0.06)',
      marginBottom: 24,
    }}>
      <h2 style={{ 
        margin: '0 0 20px', 
        fontSize: 17, 
        fontWeight: 700, 
        color: '#111827',
        display: 'flex',
        alignItems: 'center',
        gap: 8,
      }}>
        <span style={{ fontSize: 20 }}>{employee ? '✏️' : '➕'}</span>
        {employee ? 'Редактирование сотрудника' : 'Новый сотрудник'}
      </h2>
      
      <form onSubmit={handleSubmit}>
        <div style={{ display: 'grid', gap: 14 }}>

          {/* Логин и пароль — только при создании */}
          {!employee && (
            <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
              <div>
                <label style={{ 
                  fontSize: 12, 
                  fontWeight: 600, 
                  color: '#6b7280', 
                  display: 'block', 
                  marginBottom: 5 
                }}>
                  Логин <span style={{ color: '#ef4444' }}>*</span>
                </label>
                <input 
                  name="username" 
                  placeholder="username" 
                  value={form.username} 
                  onChange={handleChange} 
                  style={inputStyle}
                  onFocus={e => e.currentTarget.style.borderColor = '#2563eb'}
                  onBlur={e => e.currentTarget.style.borderColor = '#e5e7eb'}
                  required 
                />
              </div>
              <div>
                <label style={{ 
                  fontSize: 12, 
                  fontWeight: 600, 
                  color: '#6b7280', 
                  display: 'block', 
                  marginBottom: 5 
                }}>
                  Пароль <span style={{ color: '#ef4444' }}>*</span>
                </label>
                <input 
                  name="password" 
                  type="password" 
                  placeholder="••••••••" 
                  value={form.password} 
                  onChange={handleChange} 
                  style={inputStyle}
                  onFocus={e => e.currentTarget.style.borderColor = '#2563eb'}
                  onBlur={e => e.currentTarget.style.borderColor = '#e5e7eb'}
                  required 
                />
              </div>
            </div>
          )}

          <div>
            <label style={{ 
              fontSize: 12, 
              fontWeight: 600, 
              color: '#6b7280', 
              display: 'block', 
              marginBottom: 5 
            }}>
              ФИО <span style={{ color: '#ef4444' }}>*</span>
            </label>
            <input 
              name="full_name" 
              placeholder="Иванов Иван Иванович" 
              value={form.full_name} 
              onChange={handleChange} 
              style={inputStyle}
              onFocus={e => e.currentTarget.style.borderColor = '#2563eb'}
              onBlur={e => e.currentTarget.style.borderColor = '#e5e7eb'}
              required 
            />
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <div>
              <label style={{ 
                fontSize: 12, 
                fontWeight: 600, 
                color: '#6b7280', 
                display: 'block', 
                marginBottom: 5 
              }}>
                Должность <span style={{ color: '#ef4444' }}>*</span>
              </label>
              <input 
                name="position" 
                placeholder="Менеджер" 
                value={form.position} 
                onChange={handleChange} 
                style={inputStyle}
                onFocus={e => e.currentTarget.style.borderColor = '#2563eb'}
                onBlur={e => e.currentTarget.style.borderColor = '#e5e7eb'}
                required 
              />
            </div>
            <div>
              <label style={{ 
                fontSize: 12, 
                fontWeight: 600, 
                color: '#6b7280', 
                display: 'block', 
                marginBottom: 5 
              }}>
                Отдел
              </label>
              <input 
                name="department" 
                placeholder="IT-отдел" 
                value={form.department} 
                onChange={handleChange} 
                style={inputStyle}
                onFocus={e => e.currentTarget.style.borderColor = '#2563eb'}
                onBlur={e => e.currentTarget.style.borderColor = '#e5e7eb'}
              />
            </div>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: 12 }}>
            <div>
              <label style={{ 
                fontSize: 12, 
                fontWeight: 600, 
                color: '#6b7280', 
                display: 'block', 
                marginBottom: 5 
              }}>
                Телефон
              </label>
              <input 
                name="phone" 
                placeholder="+7 999 000 00 00" 
                value={form.phone} 
                onChange={handleChange} 
                style={inputStyle}
                onFocus={e => e.currentTarget.style.borderColor = '#2563eb'}
                onBlur={e => e.currentTarget.style.borderColor = '#e5e7eb'}
              />
            </div>
            <div>
              <label style={{ 
                fontSize: 12, 
                fontWeight: 600, 
                color: '#6b7280', 
                display: 'block', 
                marginBottom: 5 
              }}>
                Email
              </label>
              <input 
                name="email" 
                type="email" 
                placeholder="ivan@example.com" 
                value={form.email} 
                onChange={handleChange} 
                style={inputStyle}
                onFocus={e => e.currentTarget.style.borderColor = '#2563eb'}
                onBlur={e => e.currentTarget.style.borderColor = '#e5e7eb'}
              />
            </div>
          </div>

          <div>
            <label style={{ 
              fontSize: 12, 
              fontWeight: 600, 
              color: '#6b7280', 
              display: 'block', 
              marginBottom: 5 
            }}>
              Роль
            </label>
            <select 
              name="role" 
              value={form.role} 
              onChange={handleChange} 
              style={{ ...inputStyle, cursor: 'pointer' }}
            >
              <option value="employee">👤 Сотрудник</option>
              <option value="admin">👑 Администратор</option>
            </select>
          </div>

        </div>

        <div style={{ display: 'flex', gap: 10, marginTop: 24 }}>
          <button 
            type="submit" 
            disabled={loading}
            style={{
              background: loading 
                ? '#93c5fd' 
                : 'linear-gradient(135deg, #2563eb, #1d4ed8)',
              color: '#fff', 
              border: 'none', 
              borderRadius: 10,
              padding: '10px 24px', 
              fontWeight: 600, 
              fontSize: 14, 
              cursor: loading ? 'not-allowed' : 'pointer',
              transition: 'all 0.15s',
              boxShadow: loading ? 'none' : '0 4px 12px rgba(37,99,235,0.3)',
            }}
            onMouseEnter={e => {
              if (!loading) {
                e.currentTarget.style.transform = 'translateY(-1px)';
              }
            }}
            onMouseLeave={e => {
              if (!loading) {
                e.currentTarget.style.transform = 'translateY(0)';
              }
            }}
          >
            {loading ? '⏳ Сохранение...' : (employee ? '💾 Сохранить' : '➕ Добавить')}
          </button>
          <button 
            type="button" 
            onClick={onCancel} 
            disabled={loading}
            style={{
              background: '#f3f4f6', 
              color: '#374151', 
              border: 'none',
              borderRadius: 10, 
              padding: '10px 24px', 
              fontWeight: 600, 
              fontSize: 14, 
              cursor: loading ? 'not-allowed' : 'pointer',
              transition: 'background 0.15s',
            }}
            onMouseEnter={e => {
              if (!loading) {
                e.currentTarget.style.background = '#e5e7eb';
              }
            }}
            onMouseLeave={e => {
              if (!loading) {
                e.currentTarget.style.background = '#f3f4f6';
              }
            }}
          >
            Отмена
          </button>
        </div>
      </form>
    </div>
  );
};

export default EmployeeForm;
